\Delta \phi & =8 \times 10^{-4} \mathrm{~Wb} \\
\Delta t & =0.4 \mathrm{sec}
\end{aligned}
$$
$\therefore$ Induced emf.
$$
\begin{aligned}
e & =\frac{\Delta \phi}{\Delta t} \\
& =\frac{8 \times 10^{-4}}{0.4} \\
& =20 \times 10^{-3} \mathrm{~V}
\end{aligned}
$$

